fn solve(s: Vec<char>) -> &'static str {
    let mut stack: Vec<char> = Vec::with_capacity(s.len());
    let mut m = 0;

    for &ch in &s {
        if let Some(&top) = stack.last() {
            if top == ch {
                // Found a matching adjacent pair, remove it
                stack.pop();
                m += 1;
                continue;
            }
        }
        // Otherwise push current character onto the stack
        stack.push(ch);
    }

    if m % 2 == 1 {
        "Yes"
    } else {
        "No"
    }
}

